function ReviewTable({ reviews, onSelect, filter='All reviews' }) { const [sort,setSort]=useState('Recent'); const visible = reviews.filter(r=>filter==='All reviews'||(filter==='Needs review'&&r.status==='Needs review')||(filter==='In review'&&r.status==='In review')||(filter==='Approved'&&r.status==='Approved')); return <div className="table-wrap"><table className="review-table"><thead><tr><th>CREATIVE</th><th>SUBMITTED BY</th><th>STATUS</th><th>FINDINGS</th><th>LAST UPDATED</th><th></th></tr></thead><tbody>{visible.map((r,i)=><tr key={r.id} onClick={()=>onSelect(r)} className="click-row"><td><div className="creative-cell"><div className={`file-thumb ${r.color}`}><FileImage size={19}/></div><div><strong>{r.title}</strong><small>{r.id} <span>·</span> {r.type}</small></div></div></td><td><div className="submitter"><Avatar initials={r.owner.split(' ').map(x=>x[0]).join('').slice(0,2)} size="sm" color={i%2?'blue':'peach'}/><span>{r.owner}</span></div></td><td><Badge kind={statusClass(r.status)} dot>{r.status}</Badge></td><td><span className={r.issues?'issue-count':'issue-zero'}>{r.issues||<Check size={13}/>} {r.issues?'issues':'Clear'}</span></td><td className="date-cell">{r.date}</td><td><button className="icon-button small" onClick={e=>{e.stopPropagation();onSelect(r)}}><MoreHorizontal size={18}/></button></td></tr>)}</tbody></table>{visible.length===0&&<div className="empty-state">No reviews in this view.</div>}</div>; }
function ActivityFeed() { const items=[['Aarav Mehta','submitted a new creative','Summer launch · Social campaign','10 min ago','purple'],['Priya Shah','resolved a finding','Everyday wellness · Product banner','42 min ago','green'],['Maya Kapoor','requested changes','New collection · Landing page hero','2 hours ago','orange'],['System','completed automated checks','Monsoon essentials · Packaging','Yesterday','blue']]; return <div className="activity-list">{items.map((x,i)=><div className="activity-item" key={i}><Avatar initials={x[0]==='System'?'AI':x[0].split(' ').map(s=>s[0]).join('')} size="sm" color={x[4]}/><div className="activity-copy"><p><strong>{x[0]}</strong> {x[1]}</p><span>{x[2]}</span><small>{x[3]}</small></div></div>)}</div>; }
function HealthPanel() { return <div className="health-panel"><div className="health-head"><div><span className="eyebrow">WORKSPACE HEALTH</span><h3>You're in good shape</h3><p>Most creatives are moving smoothly through review.</p></div><span className="health-orbit"><ShieldCheck size={24}/></span></div><div className="health-metrics"><div><span>On-time approvals</span><strong>92%</strong><Progress value={92} color="green"/></div><div><span>Open findings resolved</span><strong>74%</strong><Progress value={74} color="purple"/></div></div><div className="health-foot"><span><span className="health-dot"/>No service issues</span><button>View report <ArrowRight size={13}/></button></div></div>; }
